function wasource(mixed $v):string{$s=wan($v);if(str_contains($s,'passenger')&&str_contains($s,'web'))return'passenger_website';if(str_contains($s,'passenger')&&(str_contains($s,'app')||str_contains($s,'mobile')))return'passenger_app';if(str_contains($s,'driver')&&str_contains($s,'web'))return'driver_website';if(str_contains($s,'driver')&&(str_contains($s,'app')||str_contains($s,'mobile')))return'driver_app';if(in_array($s,['website','web'],true))return'passenger_website';if(in_array($s,['app','mobile','android','ios'],true))return'passenger_app';return'unknown';}
