function wacat(array $r):string{$v=wan($r['category']??$r['context']??$r['intent']??'general_help');return match(true){str_contains($v,'ride')||str_contains($v,'book')=>'ride_booking',str_contains($v,'location')||str_contains($v,'track')=>'driver_location',str_contains($v,'pay')=>'payments',str_contains($v,'account')=>'account',str_contains($v,'verif')||str_contains($v,'approval')=>'verification',str_contains($v,'safe')||str_contains($v,'sos')=>'safety',str_contains($v,'lost')=>'lost_found',default=>$v?:'general_help'};}
function waexplicit(array $r):bool{$status=wan($r['status']??$r['escalationStatus']??'');$flag=($r['isEscalated']??false)===true||wan($r['isEscalated']??'')==='true'||($r['needsHumanSupport']??false)===true||wan($r['needsHumanSupport']??'')==='true';return$flag||wat($r,['escalationReason'])!==''&&in_array($status,['new','open','pending','in_review','waiting_for_user','resolved','closed'],true);}
