function waprof(array $profiles,string $uid,string $role,array $row):array{$p=$profiles[$uid]??[];$name=wat($p,['fullName','name'],wat($row,['userName','passengerName','driverName'],'User profile unavailable'));$initials='';foreach(array_slice(preg_split('/\s+/',trim($name))?:[],0,2)as$part)$initials.=strtoupper(substr($part,0,1));return['id'=>$uid,'name'=>$name,'initials'=>$initials?:'U','role'=>$role,'email'=>wat($p,['email'],wat($row,['userEmail','passengerEmail','driverEmail']))];}
