 $profiles=[];foreach(['users','passengers','drivers']as$collection){try{foreach(admin_list_collection($collection,1000)as$p){$uid=wat($p,['uid','userId']);if($uid!=='')$profiles[$uid]=array_merge($profiles[$uid]??[],$p);}}catch(Throwable $e){error_log("WOW Assistant optional {$collection} profiles: ".$e->getMessage());}}
 $escalationDocs=[];foreach(['supportEscalations','assistantEscalations','supportTickets']as$collection){try{foreach(admin_list_recent_collection($collection,200,'createdAt')as$r){$r['_collection']=$collection;$key=wat($r,['escalationId','ticketId','uid']);if($key!==''&&!isset($escalationDocs[$key]))$escalationDocs[$key]=$r;}}catch(Throwable $e){error_log("WOW Assistant optional {$collection}: ".$e->getMessage());}}
 $conversations=[];$seen=[];foreach(['chatbotMessages','wowAssistantInteractions']as$collection){try{foreach(admin_list_recent_collection($collection,500,'createdAt')as$r){$id=wat($r,['messageId','uid']);if($id===''||isset($seen[$id]))continue;$seen[$id]=true;$uid=wat($r,['userId','userUid']);$role=wan($r['userRole']??$r['userType']??'passenger');if(!in_array($role,['passenger','driver'],true))$role='passenger';$explicit=waexplicit($r);$profile=waprof($profiles,$uid,$role,$r);$source=wasource($r['sourcePlatform']??$r['source']??$r['platform']??'');$created=wad($r['createdAt']??null);$answered=wad($r['respondedAt']??$r['responseAt']??null);$responseMs=is_numeric($r['responseTimeMs']??null)?(float)$r['responseTimeMs']:($created&&$answered?max(0,($answered->getTimestamp()-$created->getTimestamp())*1000):null);$feedback=wan($r['feedback']??$r['helpful']??'');$conversations[]=['id'=>$id,'conversation_id'=>wat($r,['conversationId','sessionId'],$uid.'-'.($created?->format('Ymd')??$id)),'user'=>$profile,'question'=>wat($r,['message','question']),'answer'=>wat($r,['botReply','response','assistantAnswer']),'category'=>wacat($r),'outcome'=>waoutcome($r,$explicit),'source'=>$source,'source_label'=>wasource_label($source),'created_at'=>$created?->format(DATE_ATOM),'response_ms'=>$responseMs,'helpful'=>in_array($feedback,['helpful','yes','true','1'],true)?true:(in_array($feedback,['unhelpful','no','false','0'],true)?false:null),'is_escalated'=>$explicit,'related_ride_id'=>wat($r,['relatedRideId','rideId'])];}}catch(Throwable $e){error_log("WOW Assistant {$collection}: ".$e->getMessage());}}
 $escalations=[];foreach($escalationDocs as$id=>$r){$uid=wat($r,['userId','userUid']);$role=wan($r['userRole']??$r['role']??'passenger');$source=wasource($r['sourcePlatform']??$r['source']??'');$created=wad($r['createdAt']??null);$escalations[]=['id'=>$id,'user'=>waprof($profiles,$uid,$role,$r),'query'=>wat($r,['question','message','query'],'Support request'),'category'=>wacat($r),'reason'=>wat($r,['escalationReason','reason'],'Human support requested'),'source'=>$source,'source_label'=>wasource_label($source),'status'=>wan($r['status']??'new')?:'new','created_at'=>$created?->format(DATE_ATOM),'conversation_id'=>wat($r,['conversationId']),'related_ride_id'=>wat($r,['relatedRideId','rideId']),'related_payment_id'=>wat($r,['relatedPaymentId','paymentId']),'related_sos_id'=>wat($r,['relatedSosId','sosId']),'admin_response'=>wat($r,['adminResponse','resolutionNotes'])];}
 usort($conversations,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));usort($escalations,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));$sessions=[];$answeredCount=0;$fallback=0;$times=[];$feedback=[];$cats=[];foreach($conversations as$r){$sessions[$r['conversation_id']]=1;$cats[$r['category']]=($cats[$r['category']]??0)+1;if($r['outcome']==='answered')$answeredCount++;if($r['outcome']==='fallback')$fallback++;if($r['response_ms']!==null)$times[]=$r['response_ms'];if($r['helpful']!==null)$feedback[]=$r['helpful'];}$open=count(array_filter($escalations,fn($r)=>!in_array($r['status'],['resolved','closed'],true)));$summary=['total_conversations'=>count($sessions),'answered_successfully'=>$answeredCount,'escalated_to_support'=>count($escalations),'open_escalations'=>$open,'average_response_ms'=>$times?round(array_sum($times)/count($times)):null,'helpful_rate'=>$feedback?round(count(array_filter($feedback))*100/count($feedback),1):null,'feedback_count'=>count($feedback),'fallback_rate'=>$conversations?round($fallback*100/count($conversations),1):null,'escalation_rate'=>$conversations?round(count($escalations)*100/count($conversations),1):null];arsort($cats);
 waj(['ok'=>true,'summary'=>$summary,'conversations'=>$conversations,'escalations'=>$escalations,'analytics'=>['categories'=>$cats,'outcomes'=>['answered'=>$answeredCount,'fallback'=>$fallback,'escalated'=>count($escalations),'feedback'=>count($feedback)],'topics'=>array_slice($cats,0,6,true)],'collections'=>['conversations'=>['chatbotMessages','wowAssistantInteractions'],'escalations'=>array_values(array_unique(array_map(fn($r)=>$r['_collection']??'supportEscalations',$escalationDocs)))]]);
